```go
package cli

import (
    "context"
    "fmt"

    "github.com/entireio/cli/cmd/entire/cli/paths"
    "github.com/entireio/cli/cmd/entire/cli/trailers"
    "github.com/go-git/go-git/v6"
    "github.com/go-git/go-git/v6/plumbing"
    "github.com/go-git/go-git/v6/plumbing/object"
)

func createReviewCommit(ctx context.Context, md trailers.ReviewMetadata) (plumbing.Hash, error) {
    repoRoot, err := paths.WorktreeRoot(ctx)
    if err != nil {
        return plumbing.ZeroHash, err
    }
    repo, err := git.PlainOpen(repoRoot)
    if err != nil {
        return plumbing.ZeroHash, err
    }
    head, err := repo.Head()
    if err != nil {
        return plumbing.ZeroHash, fmt.Errorf("resolve HEAD: %w", err)
    }
    parent, err := repo.CommitObject(head.Hash())
    if err != nil {
        return plumbing.ZeroHash, err
    }
    // Record SHA reviewed up to BEFORE creating the empty commit so
    // Reviewed-Up-To doesn't point at the review commit itself.
    md.ReviewedUpTo = head.Hash().String()

    message := trailers.AppendReviewTrailers("Review\n", md)

    author, email, err := gitIdentity(repoRoot)
    if err != nil {
        return plumbing.ZeroHash, err
    }
    commit := &object.Commit{
        Author:       object.Signature{Name: author, Email: email, When: time.Now()},
        Committer:    object.Signature{Name: author, Email: email, When: time.Now()},
        Message:      message,
        TreeHash:     parent.TreeHash, // empty commit: same tree as parent
        ParentHashes: []plumbing.Hash{parent.Hash},
    }
    obj := repo.Storer.NewEncodedObject()
    if err := commit.Encode(obj); err != nil {
        return plumbing.ZeroHash, err
    }
    hash, err := repo.Storer.SetEncodedObject(obj)
    if err != nil {
        return plumbing.ZeroHash, err
    }
    // Advance the current branch to point at this new commit.
    ref := plumbing.NewHashReference(head.Name(), hash)
    if err := repo.Storer.SetReference(ref); err != nil {
        return plumbing.ZeroHash, err
    }
    return hash, nil
}
```

`gitIdentity(repoRoot)` reads `user.name` / `user.email` from git config — likely a helper exists already (grep `user.email`).

