    reviewCheckpointTrailerRegex = regexp.MustCompile(ReviewCheckpointTrailerKey + `:\s*([a-f0-9]{12})`)
    reviewedUpToTrailerRegex     = regexp.MustCompile(ReviewedUpToTrailerKey + `:\s*([a-f0-9]{40})`)
