    author, _ := GetGitAuthor(ctx)
    by := ""
    if author != nil {
        by = author.Email
    }
    // TODO(v2): detect clean reviews; for now default to closed.
    status := trailers.ReviewStatusClosed
    md := trailers.ReviewMetadata{
        By:         by,
