        Skills:     state.ReviewSkills,
        Session:    sessionID,
        Checkpoint: checkpointID,
        Status:     status,
    }
    hash, err := createReviewCommit(ctx, md)
    if err != nil {
        return err
    }
    // Record close in session state.
    state.ReviewStatus = session.ReviewStatus(status)
    store, err := session.NewStateStore(ctx)
